600	/**
601	 * Called every frame via requestAnimationFrame.
602	 * Calculates dt (capped at MAX_DT ms), runs all update and render passes,
603	 * then re-queues itself for the next frame.
604	 *
605	 * @param {DOMHighResTimeStamp} timestamp RAF timestamp in ms
606	 */
607	R.loop = function (timestamp) {
608	  // --- delta-time with spiral-of-death protection -----------------------
609	  if (R._lastTimestamp === undefined) {
610	    R._lastTimestamp = timestamp;
611	  }
612	  var rawDt = timestamp - R._lastTimestamp;
613	  R._lastTimestamp = timestamp;
614	  var dt = Math.min(rawDt, R.CONFIG.MAX_DT) / 1000; // ms → seconds
615	  R.state.time += dt;
616	
617	  // --- update phase -----------------------------------------------------
618	  _callIfExists('updateInput');
619	
620	  R.updateStateMachine(dt);
621	
622	  var racing = R.state.phase === 'racing';
623	  var paused = R.state.phase === 'paused';
624	
625	  if (racing && !paused) {
626	    if (typeof R.updatePlayer === 'function') { R.updatePlayer(dt); }
627	    if (typeof R.updateAI === 'function')     { R.updateAI(dt); }
628	    if (typeof R.checkCollisions === 'function') { R.checkCollisions(); }
629	  }
630	
631	  // Sync R.cars for HUD/minimap/results (player + all AI cars)
632	  if (R.player) {
633	    R.cars = [R.player].concat(R.aiCars || []);
634	  } else {
635	    R.cars = R.aiCars || [];
636	  }
637	
638	  if (typeof R.updateCamera === 'function')  { R.updateCamera(dt); }
639	  if (typeof R.updateEffects === 'function') { R.updateEffects(dt); }
640	  if (typeof R.updateHUD === 'function')     { R.updateHUD(dt); }
641	
642	  // --- render phase -----------------------------------------------------
643	  R.render();
644	
645	  // --- schedule next frame ----------------------------------------------
646	  requestAnimationFrame(R.loop);
647	};
