669	
670	    // ---- menu ----------------------------------------------------------
671	    case 'menu':
672	      var menuConfirm = (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) || input.confirm;
673	      if (menuConfirm) {
674	        state.phase          = 'countdown';
675	        state.countdownTimer = R.CONFIG.COUNTDOWN_DURATION;
676	        state._lastCountNum  = 4;
