845	R.updateCamera = function (dt) {
846	  var player = R.player;
847	  if (!player) return;
848	
849	  var cam    = R.camera;
850	  var smooth = R.CONFIG.CAMERA_SMOOTH;
851	  var offY   = R.CONFIG.CAMERA_OFFSET_Y;
852	
853	  // Frame-rate-independent lerp factor
854	  var t = 1 - Math.pow(1 - smooth, dt * 60);
855	
856	  // Snap on first frame (camera not yet positioned)
857	  if (cam.x === undefined || cam.y === undefined) {
858	    cam.x = player.x;
859	    cam.y = player.z + offY;
860	    return;
861	  }
862	
863	  cam.x += (player.x - cam.x) * t;
864	  cam.y += (player.z + offY - cam.y) * t;
865	};
