2628	  const p  = R.player;
2629	  if (!p || p.finished) return;
2630	
2631	  const cfg  = R.CONFIG;
2632	  const inp  = R.input;
2633	
2634	  // Clamp dt to avoid huge jumps (tab-away recovery)
2635	  const dtClamped = Math.min(dt, 0.05);
2636	  // Scale factor: physics tuned at 60 fps, so multiply by dt*60
2637	  const f = dtClamped * 60;
2638	
2639	  // ── 1. STEERING ──────────────────────────────────────────────────
2640	  const steerInput = inp.steer || 0;               // -1..0..1
2641	
2642	  // Speed-sensitive steering (tighter at low speed, wider at high)
2643	  const speedRatio = p.speed / p.maxSpeed;
2644	  const steerResponse = cfg.HANDLING * (1 + speedRatio * 0.5);
2645	  p.steerAngle += steerInput * steerResponse * f;
2646	
2647	  // Self-centering (stronger when no input)
2648	  if (Math.abs(steerInput) < 0.05) {
2649	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE, f);
2650	  } else {
2651	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE * 0.97, f);
2652	  }
2653	
2654	  // Clamp
2655	  if (p.steerAngle > cfg.MAX_STEER) p.steerAngle = cfg.MAX_STEER;
2656	  if (p.steerAngle < -cfg.MAX_STEER) p.steerAngle = -cfg.MAX_STEER;
2657	
2658	  // ── 2. ACCELERATION / BRAKING ────────────────────────────────────
2659	  const throttle = inp.throttle || 0;
2660	  const brake    = inp.brake    || 0;
2661	  const boost    = inp.boost    || 0;
2662	
2663	  // Boost activation
2664	  if (boost && !p.boosting && p.boostCooldown <= 0 && p.speed > 0.5) {
2665	    p.boosting     = true;
2666	    p.boostTimer   = cfg.BOOST_DURATION;
2667	    p.boostCooldown = cfg.BOOST_COOLDOWN + cfg.BOOST_DURATION;
2668	  }
2669	
2670	  // Boost timer
2671	  if (p.boosting) {
